// Write-once fault fixtures, never modifies the original census.
#include "json.hpp"
#include <openssl/sha.h>
#include <filesystem>
#include <iomanip>
#include <iostream>
static void check(bool b,const char*s){if(!b)throw std::runtime_error(s);}
static std::string read(const std::string&p){std::ifstream f(p,std::ios::binary);check(bool(f),"mutation input missing");std::ostringstream s;s<<f.rdbuf();return s.str();}
static std::string hash(const std::string&s){unsigned char h[32];SHA256(reinterpret_cast<const unsigned char*>(s.data()),s.size(),h);std::ostringstream o;for(auto b:h)o<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(b);return o.str();}
int main(int argc,char**argv){try{check(argc==4,"block-tune-mutate MODE ORIGINAL NEW_OUTPUT");std::string mode=argv[1],source=argv[2],target=argv[3];check(mode=="wrong-counter"||mode=="missing-row"||mode=="duplicate-row"||mode=="wrong-arm","mutation mode");check(!std::filesystem::exists(target),"mutation output write-once");auto raw=read(source+"/scan.csv");auto first=raw.find('\n'),second=raw.find('\n',first+1);check(first!=std::string::npos&&second!=std::string::npos,"mutation CSV shape");auto row=raw.substr(first+1,second-first-1);if(mode=="missing-row")raw.erase(first+1,second-first);else if(mode=="duplicate-row")raw+=row+'\n';else{std::vector<std::string> fields;std::istringstream in(row);std::string field;while(std::getline(in,field,','))fields.push_back(field);check(fields.size()==16,"mutation fields");if(mode=="wrong-counter")fields[5]=std::to_string(std::stoull(fields[5])+1);else fields[1]=fields[1]=="relation"?"binary":"relation";std::string replacement;for(size_t i=0;i<fields.size();++i){if(i)replacement+=',';replacement+=fields[i];}raw.replace(first+1,second-first-1,replacement);}auto receipt=read_json(source+"/producer.json");Json digest;digest.kind=Json::String;digest.value=hash(raw);receipt.object["scan_sha256"]=digest;std::filesystem::create_directories(target);std::ofstream csv(target+"/scan.csv",std::ios::binary);csv<<raw;csv.close();check(bool(csv),"mutation CSV write");std::ofstream out(target+"/producer.json");out<<canonical_json(receipt)<<'\n';check(bool(out),"mutation receipt write");std::cout<<"{\"write_once_fault_fixture\":true,\"timing_performed\":false}\n";return 0;}catch(const std::exception&e){std::cerr<<"mutation failed: "<<e.what()<<'\n';return 1;}}
